"""Analyze sealed raw retention runs; never import runner summaries or historical observations."""
import argparse
from collections import Counter
import hashlib
import json
from pathlib import Path
import re
import statistics

METRICS = ('totalNs', 'allThreadAllocatedBytes', 'callerThreadAllocatedBytes', 'prepareNs',
           'evaluateNs', 'firstRowAfterEvaluateNs', 'consumeNs', 'closeNs', 'ledgerPeakBytes')
OWNER_FIELDS = ('ownerOrdinal', 'compileOrdinalAtOpen', 'compileOrdinalAtClose',
                'lazyValueCallsAtOpen', 'lazyValueCallsAtClose', 'probes', 'hits', 'collisions',
                'invalidations', 'unsupportedValues', 'clearCalls', 'resizes', 'rehashDiscards',
                'lowHitDisable', 'initialAdmissionRefusals', 'growthAdmissionRefusals', 'peakCapacity',
                'peakArrayBytes', 'retainedEntriesAtClose', 'capacityAtClose', 'arrayBytesAfterClose',
                'disabledAtClose', 'collectedMisses', 'weakEntryAllocations', 'ownerReferenceAllocations',
                'peakReservationBytes', 'weakRetention')
ZERO_OWNER_FIELDS = ('invalidations', 'unsupportedValues', 'rehashDiscards',
                     'initialAdmissionRefusals', 'growthAdmissionRefusals', 'arrayBytesAfterClose')
RAW_FILES = ('launch.json', 'process.json', 'console.log', 'samples.jsonl', 'root-host-audit.json',
             'direct-memo-statistics.jsonl', 'gc.log', 'validation.json')
PAIRS = (('weak', 'strong'), ('strong', 'ordinary'), ('weak', 'ordinary'))


def require(condition, message):
    if not condition:
        raise ValueError(message)


def sha(path):
    with Path(path).open('rb') as stream:
        return hashlib.file_digest(stream, 'sha256').hexdigest()


def read(path):
    return json.loads(Path(path).read_text())


def json_lines(path):
    return [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]


def frozen_protocol(cohort):
    require(sha(cohort / 'protocol.json') == (cohort / 'protocol.sha256').read_text().strip(),
            'Protocol seal mismatch')
    protocol = read(cohort / 'protocol.json')
    require(protocol['format'] == 1 and protocol['cohort'] == str(cohort), 'Wrong protocol/cohort')
    require(protocol['analyzer'] == str(Path(__file__).resolve()), 'Wrong analyzer')
    require(protocol['arms'] == ['ordinary', 'strong', 'weak'] and protocol['warmups'] == 8
            and protocol['measurements'] == 5 and len(protocol['schedule']) == 36, 'Wrong fixed design')
    require(protocol['fixtures']['fanout']['rows'] == 1152000
            and protocol['fixtures']['fanout']['checksum'] == '3123987218479850048'
            and protocol['fixtures']['shared-tail']['rows'] == 1048576
            and protocol['fixtures']['shared-tail']['checksum'] == '8327963502356915200',
            'Wrong original fixture oracles')
    orders = [('ordinary', 'strong', 'weak'), ('ordinary', 'weak', 'strong'),
              ('strong', 'ordinary', 'weak'), ('strong', 'weak', 'ordinary'),
              ('weak', 'ordinary', 'strong'), ('weak', 'strong', 'ordinary')]
    expected_order = [(i, fixture_position, fixture, position, arm)
                      for i, order in enumerate(orders)
                      for fixture_position, fixture in enumerate(
                          ('fanout', 'shared-tail') if i % 2 == 0 else ('shared-tail', 'fanout'))
                      for position, arm in enumerate(order)]
    actual_order = [(s['round'], s['fixturePosition'], s['fixture'], s['position'], s['arm'])
                    for s in protocol['schedule']]
    require(actual_order == expected_order, 'Balanced arm/fixture order changed')
    for item in protocol['inputs']:
        root = Path(item['path'])
        if item['kind'] == 'tree':
            files = [p for p in root.rglob('*') if p.is_file() and (not item['sourceOnly']
                     or p.suffix in {'.java', '.py', '.xml', '.properties'})]
            require({p.relative_to(root).as_posix() for p in files} == {f['name'] for f in item['files']},
                    'Frozen directory membership changed: ' + str(root))
            checks = [(root / f['name'], f) for f in item['files']]
        else:
            checks = [(root, item)]
        for path, expected in checks:
            require(path.stat().st_size == expected['bytes'] and sha(path) == expected['sha256'],
                    'Frozen bytes changed: ' + str(path))
    return protocol


def gc_summary(path):
    lines = Path(path).read_text().splitlines()
    require(any('Using G1' in line for line in lines), 'GC log does not identify G1')
    require(not any(cause in line for line in lines for cause in
                    ('System.gc()', 'Diagnostic Command', 'Heap Inspection Initiated GC')),
            'Explicit or diagnostic GC observed in a latency JVM')
    ids, pauses, concurrent, kinds = set(), [], [], Counter()
    for line in lines:
        event = re.search(r'GC\((\d+)\) (.*)$', line)
        if not event:
            continue
        ids.add(int(event.group(1)))
        body = event.group(2)
        duration = re.search(r' ([0-9]+(?:\.[0-9]+)?)ms$', body)
        if duration is None:
            continue
        elapsed = float(duration.group(1))
        if body.startswith('Pause '):
            pauses.append(elapsed)
            kinds[' '.join(body.split()[:2])] += 1
        elif body.startswith('Concurrent '):
            concurrent.append(elapsed)
    return {'scope': 'whole JVM: setup plus warmup plus measured queries',
            'gcIdsObserved': len(ids), 'pauseCount': len(pauses), 'pauseMs': sum(pauses),
            'pauseMaxMs': max(pauses, default=0), 'pauseKinds': dict(kinds),
            'completedConcurrentCycles': len(concurrent), 'concurrentCycleMs': sum(concurrent),
            'interpretation': 'Pause and concurrent durations are separate; do not sum them as disjoint GC time.'}


def route(sample):
    counters = sample['counters']
    return {'selections': sample['successfulSelections'],
            **{key: counters[key] for key in ('irOpened', 'irRows', 'semanticNativeCompiles',
                'compiledBinds', 'interpretedBinds', 'aggregateCompiledBinds', 'aggregateInterpretedBinds')}}


def normalized_metadata(metadata):
    result = {key: value for key, value in metadata.items() if key not in ('arm', 'store')}
    properties = {'rdf4j.lmdb.nativeValueMemo.enabled', 'rdf4j.lmdb.nativeValueMemo.retention'}
    result['jvmArguments'] = [('-Xlog:gc:file=<per-JVM>:uptime,level,tags' if arg.startswith('-Xlog:gc:file=')
                               else arg) for arg in metadata['jvmArguments']
                              if not any(arg.startswith('-D' + name + '=') for name in properties)]
    result['systemProperties'] = {key: value for key, value in metadata['systemProperties'].items()
                                  if key not in properties}
    return result


def inspect_slot(protocol, slot, require_completion):
    folder, arm = Path(slot['directory']), slot['arm']
    cohort = Path(protocol['cohort'])
    fixture = protocol['fixtures'][slot['fixture']]
    claim_file = cohort / 'claims' / f"{slot['ordinal']:02d}.json"
    claim, launch, process = read(claim_file), read(folder / 'launch.json'), read(folder / 'process.json')
    require(claim['ordinal'] == launch['ordinal'] == slot['ordinal']
            and claim['command'] == launch['argv'] == slot['command']
            and claim['cwd'] == launch['cwd'] == protocol['cwd']
            and claim['protocolSha256'] == sha(cohort / 'protocol.json'), 'Claim/command mismatch')
    require(process['exitCode'] == 0 and process['failure'] is None
            and process['startedEpochNs'] == launch['startedEpochNs'] >= claim['claimedEpochNs']
            and process['finishedEpochNs'] >= process['startedEpochNs'], 'JVM did not terminate normally')
    if require_completion:
        completion = read(folder / 'completion.json')
        require(completion['ordinal'] == slot['ordinal']
                and completion['protocolSha256'] == sha(cohort / 'protocol.json')
                and completion['claimSha256'] == sha(claim_file)
                and completion['completedEpochNs'] >= process['finishedEpochNs']
                and set(completion['rawHashes']) == set(RAW_FILES), 'Completion receipt mismatch')
        require(all(sha(folder / name) == digest for name, digest in completion['rawHashes'].items()),
                'Raw output changed after completion')
    records = json_lines(folder / 'samples.jsonl')
    require(len(records) == 14 and records[0].get('type') == 'metadata', 'Expected metadata plus 13 queries')
    metadata, samples = records[0], records[1:]
    expected = {**fixture['metadata'], **protocol['configuration'], 'arm': arm,
                'source': protocol['sourceIdentity'], 'expectedRows': fixture['rows'],
                'expectedChecksum': fixture['checksum'], 'projectedNames': fixture['names'],
                'consumption': 'full', 'warmup': 8, 'measurementsToRun': 5,
                'maxHeapBytes': 1073741824, 'javaVersion': protocol['javaVersion'],
                'namespaceExperimentHarness': 'native-and-direct-adjacency-v1'}
    require(all(metadata.get(key) == value for key, value in expected.items()), 'Fixture/JVM metadata mismatch')
    require(metadata['jvmArguments'] == slot['command'][1:slot['command'].index('-cp')],
            'Observed JVM flags differ from the frozen command')
    require(metadata['systemProperties'] == {'rdf4j.lmdb.hotCounters': 'true',
            'rdf4j.lmdb.queryMemory.perQueryMaxBytes': '536870912', **slot['properties']},
            'Observed experiment properties differ')
    setup = metadata['adjacencySetup']
    require(setup['state'] == 'ACTIVE' and setup['currentRevisionReady'] is True
            and setup['appliedRevision'] == setup['currentDataRevision'], 'Adjacency was not ready')
    require([sample['iteration'] for sample in samples] == list(range(-8, 5))
            and [sample['stage'] for sample in samples] == ['warmup'] * 8 + ['measurement'] * 5,
            'Wrong query chronology')
    for sample in samples:
        require(sample['type'] == 'sample' and sample['arm'] == arm and sample['consumption'] == 'full'
                and all(sample[key] is True for key in
                        ('valid', 'complete', 'rowCountValid', 'checksumValid', 'partialMembershipValid'))
                and sample['rows'] == fixture['rows'] and sample['checksum'] == fixture['checksum']
                and sample['expectedFullChecksum'] == fixture['checksum'] and sample['retainedRows'] == 0
                and sample['bindingReads'] == fixture['rows'] * len(fixture['names']), 'Result oracle failed')
        if slot['fixture'] == 'shared-tail':
            require(sample['exactBagValid'] is True, 'Shared-tail independent exact bag oracle failed')
        require(sample['ledgerBeforeBytes'] == sample['ledgerAfterBytes'] == 0 and sample['ledgerReleased'],
                'Query ledger did not release')
        require(all(type(sample[key]) is int and sample[key] >= 0 for key in METRICS)
                and sample['totalNs'] > 0 and sample['allThreadAllocatedBytes'] > 0, 'Invalid measured counter')
        counters, adjacency = sample['counters'], sample['adjacency']
        require(sample['autoRequested'] and sample['auto'] and sample['successfulSelections']
                and not any('forced' in s['mode'] for s in sample['successfulSelections'])
                and counters['semanticNativeCompiles'] == counters['irOpened'] == 1
                and counters['irRows'] == fixture['rows'] and counters['lazyValueCalls'] >= 0,
                'Normal AUTO/native route not observed')
        admission = counters['coordinateAdmissions']
        require(admission['opened'] == admission['initialAdmissionRefused'] == admission['growthAdmissionRefused'] == 0,
                'Coordinate transport is not off or refused unexpectedly')
        if sample['stage'] == 'measurement':
            require(counters['compiledBinds'] == 1 and counters['interpretedBinds'] ==
                    counters['aggregateCompiledBinds'] == counters['aggregateInterpretedBinds'] == 0,
                    'Measured query did not use compiled row IR')
        require(adjacency['stateBefore'] == adjacency['stateAfter'] == 'ACTIVE'
                and adjacency['appliedRevisionBefore'] == adjacency['currentRevisionBefore'] ==
                adjacency['appliedRevisionAfter'] == adjacency['currentRevisionAfter'] == setup['currentDataRevision']
                and adjacency['lookupHits'] > 0, 'Adjacency route/readiness changed')
    audit = read(folder / 'root-host-audit.json')
    require(audit['format'] == 1 and audit['type'] == 'root-host-audit' and audit['harnessReturned']
            and audit['harnessFailureClass'] is None and audit['hostedGenericTotal'] == 0
            and audit['semanticNativeCompilesTotal'] == 13 and audit['harnessMain'] == fixture['main']
            and audit['readPhase'] == fixture['readPhase'], 'Root-route audit failed')
    stats = json_lines(folder / 'direct-memo-statistics.jsonl')
    count = 0 if arm == 'ordinary' else 13
    require(len(stats) == count + 1, 'Wrong number of memo owners')
    header, owners = stats[0], stats[1:]
    require(header['type'] == 'memoStatisticsMetadata' and header['format'] == protocol['statisticsFormat'] == 2
            and header['scope'] == protocol['statisticsScope'] and header['fixture'] == slot['fixture']
            and header['delegateLauncher'] == fixture['launcher'] and header['harnessReturned']
            and header['harnessFailureClass'] is None and header['capacity'] == 13
            and header['opened'] == header['closed'] == header['size'] == count
            and header['overflowCount'] == 0, 'Memo lifecycle metadata failed')
    previous_close = None
    for index, owner in enumerate(owners):
        require(set(owner) == {'type', 'recordIndex', *OWNER_FIELDS} and owner['type'] == 'owner'
                and owner['recordIndex'] == index
                and all(type(owner[key]) is int and owner[key] >= 0 for key in OWNER_FIELDS), 'Malformed owner record')
        require(owner['ownerOrdinal'] == owner['compileOrdinalAtOpen'] == owner['compileOrdinalAtClose'] == index + 1,
                'Memo does not map one-to-one to native queries')
        require(owner['lazyValueCallsAtClose'] - owner['lazyValueCallsAtOpen'] == samples[index]['counters']['lazyValueCalls']
                and (previous_close is None or owner['lazyValueCallsAtOpen'] == previous_close),
                'Memo resolver interval differs from query counters')
        previous_close = owner['lazyValueCallsAtClose']
        probes, peak, resizes = owner['probes'], owner['peakCapacity'], owner['resizes']
        require(probes > 0 and sum(owner[k] for k in ('hits', 'collisions', 'invalidations', 'collectedMisses')) <= probes,
                'Impossible probe partition')
        require(all(owner[key] == 0 for key in ZERO_OWNER_FIELDS), 'Mutation/refusal/cleanup invariant failed')
        require(0 <= resizes <= 4 and peak == 4096 << resizes
                and (resizes == 0 or probes >= 8192 * (resizes + 1)), 'Invalid growth history')
        weak = int(arm == 'weak')
        require(owner['weakRetention'] == weak and owner['ownerReferenceAllocations'] <= owner['weakEntryAllocations'],
                'Wrong retention mode or owner-reference allocation count')
        if not weak:
            require(owner['collectedMisses'] == owner['weakEntryAllocations'] == owner['ownerReferenceAllocations'] == 0,
                    'Strong arm exported weak events')
        reservation = protocol['metadataReservation']
        def array_bytes(capacity):
            return reservation['arrayBase'] + reservation['arrayPerSlot'] * capacity
        def reserved_bytes(capacity):
            return array_bytes(capacity) + weak * (reservation['weakMetadataPerSlot'] * capacity
                                                   + reservation['weakMetadataOverlap'])
        arrays = array_bytes(peak) + (array_bytes(peak // 2) if resizes else 0)
        reserved = reserved_bytes(peak) + (reserved_bytes(peak // 2) if resizes else 0)
        require(owner['peakArrayBytes'] == arrays and owner['peakReservationBytes'] == reserved
                and reserved <= samples[index]['ledgerPeakBytes'], 'Memo accounting differs from its reservation formula')
        require(owner['disabledAtClose'] == owner['lowHitDisable'] in (0, 1)
                and owner['retainedEntriesAtClose'] <= owner['capacityAtClose'], 'Invalid close/adaptation state')
        if owner['lowHitDisable']:
            require(probes == 8192 and 4 * owner['hits'] < probes and resizes == 0
                    and owner['capacityAtClose'] == owner['retainedEntriesAtClose'] == 0, 'Invalid first-window cutoff')
        else:
            require(owner['capacityAtClose'] == peak and (probes < 8192 or 4 * owner['hits'] >= 8192),
                    'Active table violates its first-window invariant')
    measured = samples[8:]
    medians = {key: statistics.median(sample[key] for sample in measured) for key in METRICS}
    medians['lazyValueCalls'] = statistics.median(sample['counters']['lazyValueCalls'] for sample in measured)
    owner_medians = {key: statistics.median(owner[key] for owner in owners[8:]) for key in OWNER_FIELDS} if owners else {}
    if owners:
        owner_medians['hitRate'] = statistics.median(owner['hits'] / owner['probes'] for owner in owners[8:])
    return {'ordinal': slot['ordinal'], 'round': slot['round'], 'fixture': slot['fixture'], 'arm': arm,
            'directory': str(folder), 'metadata': metadata, 'samples': samples, 'owners': owners,
            'process': process, 'medians': medians, 'ownerMedians': owner_medians,
            'gc': gc_summary(folder / 'gc.log')}


def match_runs(runs):
    metadata, indexed = {}, {}
    previous_end = 0
    for run in runs:
        require(run['process']['startedEpochNs'] >= previous_end, 'Overlapping JVMs')
        previous_end = run['process']['finishedEpochNs']
        fixture = run['fixture']
        normalized = normalized_metadata(run['metadata'])
        metadata.setdefault(fixture, normalized)
        require(metadata[fixture] == normalized, 'Matched fixture metadata differs')
        key = (fixture, run['round'], run['arm'])
        require(key not in indexed, 'Duplicate arm/round/fixture')
        indexed[key] = run
    paired_queries = 0
    for fixture, round_index in {(fixture, round_index) for fixture, round_index, arm in indexed}:
        for candidate, comparator in PAIRS:
            a, b = indexed.get((fixture, round_index, candidate)), indexed.get((fixture, round_index, comparator))
            if a is None or b is None:
                continue
            for left, right in zip(a['samples'], b['samples'], strict=True):
                require(left['iteration'] == right['iteration'] and left['stage'] == right['stage']
                        and route(left) == route(right) and left['adjacency'] == right['adjacency'],
                        'Paired query route/tier/adjacency differs')
                paired_queries += 1
    return paired_queries


def summarize(protocol, runs):
    require(len(runs) == 36 and [run['ordinal'] for run in runs] == list(range(36)),
            'No accepted estimates from an incomplete cohort')
    require(match_runs(runs) == 468, 'Expected 468 matched query-pair checks')
    indexed = {(run['fixture'], run['round'], run['arm']): run for run in runs}
    comparisons, absolutes = [], []
    for fixture in protocol['fixtures']:
        for arm in protocol['arms']:
            selected = [indexed[fixture, i, arm] for i in range(6)]
            absolutes.append({'fixture': fixture, 'arm': arm,
                'medianOfJvmMedians': {key: statistics.median(run['medians'][key] for run in selected)
                                       for key in selected[0]['medians']},
                'ownerMedianOfJvmMedians': {key: statistics.median(run['ownerMedians'][key] for run in selected)
                                            for key in selected[0]['ownerMedians']},
                'wholeJvmGcMedians': {key: statistics.median(run['gc'][key] for run in selected)
                                      for key in ('gcIdsObserved', 'pauseCount', 'pauseMs',
                                                  'completedConcurrentCycles', 'concurrentCycleMs')}})
        for candidate, comparator in PAIRS:
            pairs = []
            for i in range(6):
                a, b = indexed[fixture, i, candidate], indexed[fixture, i, comparator]
                ratios = {key: a['medians'][key] / b['medians'][key] if b['medians'][key] else None
                          for key in a['medians']}
                pairs.append({'round': i, 'ratios': ratios})
            metrics = {}
            for key in pairs[0]['ratios']:
                values = [pair['ratios'][key] for pair in pairs if pair['ratios'][key] is not None]
                metrics[key] = {'medianRatio': statistics.median(values) if values else None,
                                'range': [min(values), max(values)] if values else None,
                                'pairedRatios': [pair['ratios'][key] for pair in pairs]}
            comparisons.append({'fixture': fixture, 'candidate': candidate, 'comparator': comparator,
                                'metrics': metrics})
    return {'complete': True, 'protocolSha256': sha(Path(protocol['cohort']) / 'protocol.json'),
            'counts': {'jvms': 36, 'queries': 468, 'warmups': 288, 'measurements': 180, 'pairedQueries': 468},
            'allResultRouteAndCleanupGatesPassed': True, 'estimator': protocol['estimator'],
            'pooling': protocol['pooling'], 'memoryScope': protocol['memoryScope'], 'gcScope': protocol['gcScope'],
            'decision': protocol['decision'], 'absolutes': absolutes, 'comparisons': comparisons,
            'jvmResults': [{key: run[key] for key in ('ordinal', 'round', 'fixture', 'arm', 'directory',
                                                    'medians', 'ownerMedians', 'gc')} for run in runs]}


def markdown(result):
    lines = ['# Fresh strong versus weak memo comparison', '',
             'All 36 scheduled JVMs and all 468 queries completed. The 180 measured queries passed result, route, '
             'adjacency and cleanup gates. Each ratio pairs JVM medians within the same round and fixture.', '',
             '| Fixture | Comparison | Latency ratio | Six-pair range | Allocation ratio |',
             '| --- | --- | ---: | ---: | ---: |']
    for comparison in result['comparisons']:
        latency = comparison['metrics']['totalNs']
        allocation = comparison['metrics']['allThreadAllocatedBytes']
        lines.append(f"| {comparison['fixture']} | {comparison['candidate']}/{comparison['comparator']} | "
                     f"{latency['medianRatio']:.6f} | {latency['range'][0]:.6f}–{latency['range'][1]:.6f} | "
                     f"{allocation['medianRatio']:.6f} |")
    lines += ['', 'A ratio below 1 favors the numerator. These are descriptive engineering results, '
              'not a significance test or a production-promotion gate.', '',
              '| Fixture | Arm | Median query seconds | Allocation bytes | Preparation ms | Ledger peak bytes | Resolver calls |',
              '| --- | --- | ---: | ---: | ---: | ---: | ---: |']
    for entry in result['absolutes']:
        m = entry['medianOfJvmMedians']
        lines.append(f"| {entry['fixture']} | {entry['arm']} | {m['totalNs'] / 1e9:.6f} | "
                     f"{m['allThreadAllocatedBytes']:.0f} | {m['prepareNs'] / 1e6:.6f} | "
                     f"{m['ledgerPeakBytes']:.0f} | {m['lazyValueCalls']:.0f} |")
    lines += ['', 'These absolute figures are medians of six JVM medians. Ledger charges are accounting values: '
              'strong mode charges arrays; weak mode also reserves conservative weak-reference metadata. '
              'Neither number is total retained heap.', '',
              '| Fixture | Arm | Whole-JVM GC pauses | Pause ms | Concurrent cycles | Concurrent-cycle ms |',
              '| --- | --- | ---: | ---: | ---: | ---: |']
    for entry in result['absolutes']:
        g = entry['wholeJvmGcMedians']
        lines.append(f"| {entry['fixture']} | {entry['arm']} | {g['pauseCount']:g} | {g['pauseMs']:.3f} | "
                     f"{g['completedConcurrentCycles']:g} | {g['concurrentCycleMs']:.3f} |")
    lines += ['', 'GC figures cover the whole JVM, including fixture setup and warmups. Concurrent-cycle time '
              'overlaps other work and is not added to pause time. No forced collections or profiles were used.', '',
              'The JSON contains all six paired ratios, per-JVM medians and weak-reference counters. '
              'Historical observations, diagnostics and warmups are excluded from the latency estimator.', '']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--cohort', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    cohort = args.cohort.resolve(strict=True)
    require(not (cohort / 'failure.json').exists(), 'Cohort has a permanent failure')
    protocol = frozen_protocol(cohort)
    claims = sorted((cohort / 'claims').iterdir())
    require([p.name for p in claims] == [f'{i:02d}.json' for i in range(36)], 'Incomplete or extra claim set')
    require({p.name for p in cohort.glob('round-*')} == {Path(s['directory']).name for s in protocol['schedule']},
            'Unclaimed, missing or extra run directory')
    runs = [inspect_slot(protocol, slot, require_completion=True) for slot in protocol['schedule']]
    result = summarize(protocol, runs)
    output = args.output.resolve()
    output.mkdir(parents=True, exist_ok=False)
    (output / 'results.json').write_text(json.dumps(result, indent=2, sort_keys=True) + '\n')
    (output / 'RESULTS.md').write_text(markdown(result))
    print(json.dumps({'complete': True, 'counts': result['counts'], 'output': str(output)}))


if __name__ == '__main__':
    main()
